import punycode from 'punycode.js';
import * as mdurl from 'mdurl';

const RECODE_HOSTNAME_FOR = ['http:', 'https:', 'mailto:'];

// Simulating normalizeLink as written in source code
function buggyNormalizeLink(url) {
  const parsed = mdurl.parse(url, true);

  if (parsed.hostname) {
    // BUG HERE: indexOf returns 0 for 'http:', and 0 > 0 is false
    if (!parsed.protocol || RECODE_HOSTNAME_FOR.indexOf(parsed.protocol) > 0) {
      console.log(`  -> Will toASCII: protocol='${parsed.protocol}', index=${RECODE_HOSTNAME_FOR.indexOf(parsed.protocol)}`);
      try {
        parsed.hostname = punycode.toASCII(parsed.hostname);
      } catch (er) {}
    } else {
      console.log(`  -> SKIP toASCII: condition false`);
    }
  }

  if (parsed.auth) parsed.auth = mdurl.encode(parsed.auth);
  if (parsed.hostname) parsed.hostname = mdurl.encode(parsed.hostname);
  if (parsed.pathname) parsed.pathname = mdurl.encode(parsed.pathname);
  if (parsed.search) parsed.search = mdurl.encode(parsed.search);
  if (parsed.hash) parsed.hash = mdurl.encode(parsed.hash);

  return mdurl.format(parsed);
}

// Test each protocol
for (const proto of ['http:', 'https:', 'mailto:']) {
  const url = `${proto}//☃.net/`;
  console.log(`\nURL with ${proto}:`);
  const result = buggyNormalizeLink(url);
  console.log(`  Result: ${result}`);
}

// What about no protocol? (for relative URLs //host/)
console.log("\n\nURL without protocol:");
const result2 = buggyNormalizeLink('//☃.net/');
console.log(`  Result: ${result2}`);
